def validate_raw(topics, name):
    print(f"Validating {name} topics: count = {len(topics)}")
    assert len(topics) == 100, f"Expected 100 topics for {name}, got {len(topics)}"
    seen = set()
    for i, t in enumerate(topics):
        topic, subj, sys_name, hallmark, ref_label, ref_url = t
        assert topic not in seen, f"Duplicate topic at {i}: {topic}"
        seen.add(topic)
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject '{subj}' in {name} at {i}: {topic}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system '{sys_name}' in {name} at {i}: {topic}"
        assert len(hallmark) >= 20, f"Hallmark too short in {name} at {i}: {topic}"
        assert len(ref_label) >= 5, f"Ref label too short in {name} at {i}: {topic}"
        assert ref_url.startswith("https://"), f"Ref url must start with https:// in {name} at {i}: {ref_url}"
    print(f"  -> All 100 {name} topics PASSED validation!")

if __name__ == "__main__":
    validate_raw(AMC_RAW, "AMC")
    validate_raw(MCCQE_RAW, "MCCQE")
    
    # Save to mega86_topics_a.py
    out_file = os.path.join(os.path.dirname(__file__), "mega86_topics_a.py")
    with open(out_file, "w", encoding="utf-8") as f:
        f.write("# Auto-generated topics for Mega-Batch 86 Part A (AMC, MCCQE)\n\n")
        f.write("AMC_TOPICS = " + json.dumps(AMC_RAW, indent=2) + "\n\n")
        f.write("MCCQE_TOPICS = " + json.dumps(MCCQE_RAW, indent=2) + "\n")
    print(f"Successfully generated {out_file} with 200 topics!")
